"use client";

import { useState } from "react";
import Link from "next/link";
import Image from "next/image";

export default function Navbar() {
  const [open, setOpen] = useState(false);

  return (
    <header className="shadow-md relative z-50">
      
      {/* Main Navbar */}
      <div className="flex items-center justify-between px-6 lg:px-10 py-2
      bg-[linear-gradient(90deg,rgb(109,15,172)_0%,rgba(253,29,29,1)_60%,rgba(252,176,69,1)_100%)] text-white">
        
        {/* Logo */}
        <Link href="/" className="flex items-center">
          <Image
            src="/header-logo-12.png"
            alt="Lovely Looks"
            width={640}
            height={500}
            priority
            className="h-12 lg:h-17 w-auto "
          />
        </Link>

        {/* Desktop Menu */}
        <ul className="hidden lg:flex items-center gap-6 text-base lg:text font-semibold">
          <li>
            <Link href="/" >
              HOME
            </Link>
          </li>
          <li>
            <Link href="/service" >
              SERVICE
            </Link>
          </li>
          <li>
            <Link href="/gallery">
              GALLERY
            </Link>
          </li>
          <li>
            <Link href="/contact" >
              CONTACT
            </Link>
          </li>
        </ul>

        {/* Mobile Button */}
        <button
          onClick={() => setOpen(true)}
          className="lg:hidden text-2xl leading-none"
        >
          ☰
        </button>
      </div>

      {/* Mobile Menu */}
      {open && (
        <div className="fixed top-0 left-0 w-2/3 h-full bg-[rgb(156,8,156)] text-white shadow-lg p-6 z-[100000]">
          
          {/* Close Button */}
          <button
            onClick={() => setOpen(false)}
            className="mb-6 text-2xl"
          >
            ✕
          </button>

          {/* Logo */}
          <div className="mb-6">
            <Image
              src="/header-logo-12.png"
              alt="Lovely Looks Logo"
              width={120}
              height={40}
              className="h-10 w-auto object-contain"
            />
          </div>

          {/* Menu */}
          <ul className="space-y-6 text-lg font-bold">
            <li>
              <Link href="/" onClick={() => setOpen(false)}>
                Home
              </Link>
            </li>
            <li>
              <Link href="/service" onClick={() => setOpen(false)}>
                Service
              </Link>
            </li>
            <li>
              <Link href="/gallery" onClick={() => setOpen(false)}>
                Gallery
              </Link>
            </li>
            <li>
              <Link href="/contact" onClick={() => setOpen(false)}>
                Contact
              </Link>
            </li>
          </ul>
        </div>
      )}
    </header>
  );
}